// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(actor, amount * 2);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();
        uint256 afterFirst = actor.balance;
        vm.prank(actor);
        c.withdrawAll();
        // Rule: after one full withdrawal, further withdrawAll calls are no-ops,
        // so the caller's balance never grows beyond the deposited amount.
        assertTrue(actor.balance == afterFirst, "repeat withdrawAll must be a no-op");
    }
}
